import{_ as t,o,c as n,a5 as s}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Plan — Content Writing View (FR 3.6.10)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writting-view/plan.md","filePath":"feature/content-task-workflow/3-6-10-content-writting-view/plan.md"}'),a={name:"feature/content-task-workflow/3-6-10-content-writting-view/plan.md"};function d(c,e,i,r,l,p){return o(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan-—-content-writing-view-fr-3-6-10" tabindex="-1">Plan — Content Writing View (FR 3.6.10) <a class="header-anchor" href="#plan-—-content-writing-view-fr-3-6-10" aria-label="Permalink to &quot;Plan — Content Writing View (FR 3.6.10)&quot;">​</a></h1><p>&gt; Link: <a href="./spec.html">spec.md</a> — Document Status: <strong>Implemented</strong>. Direction B (Yjs CRDT) from §6 was the one actually built — see §2/§3/§4 below for what the shipped API/data model/flow look like, which differs slightly from the original &quot;hand-written OT&quot; sketch (§6 still documents that trade-off and why B was chosen). &gt; &gt; V4 (2026-10-01): canvas-rendering + Yjs CRDT real-time sync over STOMP WebSocket, mirroring the real Google Docs technique&#39;s effect (not its OT algorithm — see §6). See <a href="./spec.html#4-ui--ux">spec.md §4</a> and <a href="./spec.html#7-edge-cases">§7</a>. &gt; &gt; <strong>V5 (2026-10-26)</strong>: Docs/Word hybrid UI redesign (purely visual — see task.md item 13); presence/multi-cursor awareness added via a second, unpersisted STOMP channel carrying standard <code>y-protocols/awareness</code> updates (<code>handleAwareness</code> in <code>TaskContentWebSocketController</code>, same opaque-relay posture as content — see task.md item 14); and a React Native mobile port under <code>brandhub-mobile-app/src/screens/content-writing/</code> reusing the identical Yjs CRDT sync protocol over the same REST+STOMP endpoints, rendered through native <code>TextInput</code> instead of canvas (see task.md item 15 for the full rationale and what mobile intentionally doesn&#39;t cover).</p><h2 id="_1-technical-scope-implemented" tabindex="-1">1. Technical Scope (implemented) <a class="header-anchor" href="#_1-technical-scope-implemented" aria-label="Permalink to &quot;1. Technical Scope (implemented)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code> (BE), <code>brandhub-web-dashboard</code> (FE)</td></tr><tr><td>BE</td><td><code>Task</code> entity (minimal — see note below), <code>TaskContentOperation</code> (append-only, opaque base64 Yjs update log), <code>TaskContentSnapshot</code> (client-reported Yjs state checkpoints), <code>spring-boot-starter-websocket</code>, <code>WebSocketConfig</code> (STOMP endpoint <code>/ws/tasks</code>, broker <code>/topic</code>), <code>WsJwtHandshakeInterceptor</code> (JWT via query param), <code>TaskContentWebSocketController</code> (<code>@MessageMapping</code>), <code>TaskContentSnapshotJob</code> (<code>@Scheduled</code>, logs tasks due for a snapshot — can&#39;t capture one itself, see §6)</td></tr><tr><td>FE</td><td><code>CanvasTextEditor</code> (hand-written canvas rendering engine, content now backed by a Yjs <code>Y.Text</code> instead of plain React state), <code>useTaskContentSync</code> hook (REST initial load + STOMP client via <code>@stomp/stompjs</code>, client-reported snapshotting), <code>VersionHistorySidebar</code> (list/restore), <code>yjs</code> + <code>@stomp/stompjs</code> added to <code>package.json</code></td></tr><tr><td><strong>Minimal <code>Task</code>, not full FR 3.6.1</strong></td><td><code>id</code>, <code>workspaceId</code>, <code>type</code> (<code>TaskType</code> enum, only <code>POST</code> defined), <code>title</code>, <code>createdBy</code>, timestamps. No assignee, due date, comments, etc. — those belong to FR 3.6.1 Identify Task Detail, out of this scope.</td></tr><tr><td>Not implemented this pass</td><td>Accessibility shadow-DOM beyond the existing <code>aria-live</code> text mirror; virtualization for multi-page documents; offline IndexedDB queue; font auto-conversion on publish; real compaction (old operations are never pruned, only snapshotted)</td></tr></tbody></table><h2 id="_2-data-model-implemented" tabindex="-1">2. Data Model (implemented) <a class="header-anchor" href="#_2-data-model-implemented" aria-label="Permalink to &quot;2. Data Model (implemented)&quot;">​</a></h2><ul><li><code>Task</code> (table <code>tasks</code>) — see minimal scope above. Migration: <code>2026-10-01-create-tasks-table.sql</code>.</li><li><code>TaskContentOperation</code> (table <code>task_content_operations</code>) — append-only: <code>id</code>, <code>taskId</code>, <code>sequenceNumber</code> (bigint, <code>count(taskId) + 1</code> per insert), <code>yjsUpdate</code> (TEXT, base64-encoded opaque Yjs binary update — <strong>the server never decodes it</strong>, Yjs itself is the CRDT/operation log), <code>editedBy</code>, <code>createdAt</code>.</li><li><code>TaskContentSnapshot</code> (table <code>task_content_snapshots</code>) — <code>id</code>, <code>taskId</code>, <code>sequenceNumber</code>, <code>yjsState</code> (TEXT, base64-encoded <code>Y.encodeStateAsUpdate(yDoc)</code> — <strong>client-reported</strong>, not server-captured; see §6), <code>createdAt</code>.</li><li>Migration: <code>2026-10-01-create-task-content-tables.sql</code>.</li><li>This differs from the original sketch (hand-defined <code>opType</code>/<code>position</code>/<code>payload</code> columns) — Yjs updates are opaque binary, so there&#39;s nothing to decompose into those fields. See §6 for why.</li></ul><h2 id="_3-api-contract-implemented" tabindex="-1">3. API Contract (implemented) <a class="header-anchor" href="#_3-api-contract-implemented" aria-label="Permalink to &quot;3. API Contract (implemented)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/content</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;snapshot&quot;: &quot;&lt;base64|null&gt;&quot;, &quot;operationsSinceSnapshot&quot;: [&quot;&lt;base64&gt;&quot;, ...], &quot;sequenceNumber&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WS /ws/tasks?token=&lt;JWT&gt;  (STOMP; JWT via query param — WS clients can&#39;t always set an Authorization header on the upgrade request)</span></span>
<span class="line"><span>Client → Server: PUBLISH /app/tasks/{taskId}/content { &quot;update&quot;: &quot;&lt;base64 Yjs update&gt;&quot; }</span></span>
<span class="line"><span>Server → SUBSCRIBE /topic/tasks/{taskId}/content: { &quot;update&quot;, &quot;sequenceNumber&quot;, &quot;editedBy&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/content/snapshot</span></span>
<span class="line"><span>Body: { &quot;yjsState&quot;: &quot;&lt;base64&gt;&quot;, &quot;atSequenceNumber&quot; }</span></span>
<span class="line"><span>// Client-reported — see §6 &quot;server never decodes Yjs updates&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/content/versions</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;snapshotId&quot;, &quot;sequenceNumber&quot;, &quot;createdAt&quot; }] }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/content/versions/{snapshotId}/restore</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;snapshot&quot;: &quot;&lt;base64&gt;&quot;, &quot;operationsSinceSnapshot&quot;: [], &quot;sequenceNumber&quot; } }</span></span></code></pre></div><h2 id="_4-processing-flow-implemented" tabindex="-1">4. Processing Flow (implemented) <a class="header-anchor" href="#_4-processing-flow-implemented" aria-label="Permalink to &quot;4. Processing Flow (implemented)&quot;">​</a></h2><p><strong>Opening content:</strong></p><ol><li><code>findPostTaskOrThrow(workspaceId, taskId)</code> — 404 <code>TASK_NOT_FOUND</code> if missing or belongs to a different workspace; 400 <code>INVALID_TASK_TYPE_FOR_CONTENT_WRITING</code> if not type <code>POST</code>.</li><li><code>@RequireRole({MANAGER, CREATOR})</code> on <code>TaskController</code> — 403 otherwise.</li><li>REST returns the latest <code>TaskContentSnapshot</code> (if any) + every <code>TaskContentOperation</code> committed after it.</li><li>The client (<code>useTaskContentSync</code>) applies the snapshot then replays the tail via <code>Y.applyUpdate</code>, reconstructing the <code>Y.Doc</code>. It then opens a STOMP WS connection to <code>/ws/tasks?token=&lt;JWT&gt;</code> and subscribes to <code>/topic/tasks/{taskId}/content</code>.</li></ol><p><strong>Real-time editing (Yjs CRDT merge — no central transform step):</strong> 5. The Creator types → the off-screen <code>contenteditable</code> captures the event → <code>CanvasTextEditor</code> calls <code>yText.insert()/delete()</code> at the local caret — a local Yjs mutation, rendered optimistically on the canvas right away. 6. The <code>Y.Doc</code>&#39;s <code>update</code> event fires locally → <code>useTaskContentSync</code> publishes <code>{ update: base64 }</code> over STOMP. 7. <code>TaskContentWebSocketController</code> → <code>TaskContentServiceImpl.appendOperation</code>: assigns the next <code>sequenceNumber</code>, persists the opaque update, and broadcasts it to every subscriber of this Task&#39;s topic — including the sender (confirms its official <code>sequenceNumber</code>). 8. Every receiving client calls <code>Y.applyUpdate(yDoc, update, &quot;remote&quot;)</code> — Yjs merges the update into its local CRDT state automatically; no server-side transform step exists because none is needed. The canvas re-renders the affected region.</p><p><strong>Publish:</strong> 9. Font auto-conversion on publish is <strong>not implemented</strong> in this pass (see task.md).</p><p><strong>Client-reported snapshot (not a background job — see §6):</strong> 10. Once a client&#39;s <code>operationsSinceSnapshot</code> count crosses 200, it posts <code>POST .../content/snapshot</code> with its current merged Yjs state. <code>TaskContentServiceImpl.reportSnapshot</code> skips if a snapshot already exists at/after that sequence (first reporter wins), otherwise inserts a new row. 11. <code>TaskContentSnapshotJob</code> runs every 5 minutes server-side but <strong>cannot capture a snapshot itself</strong> (see §6) — it only logs which Tasks have crossed the threshold.</p><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Description</th></tr></thead><tbody><tr><td>Was blocked by</td><td>The Task entity did not exist — resolved by building the minimal version in §1, not the full FR 3.6.1 scope.</td></tr><tr><td>Blocks</td><td>None</td></tr></tbody></table><h2 id="_6-technical-risks-as-realized" tabindex="-1">6. Technical Risks (as realized) <a class="header-anchor" href="#_6-technical-risks-as-realized" aria-label="Permalink to &quot;6. Technical Risks (as realized)&quot;">​</a></h2><ul><li><p><strong>Hand-writing OT vs. integrating Yjs (CRDT) — decided: direction B (Yjs) was implemented.</strong></p><table tabindex="0"><thead><tr><th>Direction</th><th>Description</th><th>Chosen?</th></tr></thead><tbody><tr><td>A. Hand-write OT (as the real Google Docs does)</td><td><code>transform(opA, opB)</code> by hand for every operation-type pair</td><td>Not chosen — very high risk of document divergence bugs for a team not specialized in real-time editing</td></tr><tr><td><strong>B. Integrate Yjs (CRDT)</strong></td><td>Shared <code>Y.Doc</code>/<code>Y.Text</code>, updates merge automatically and commutatively on every peer</td><td><strong>Chosen and implemented</strong></td></tr></tbody></table><p>Consequence: the server (<code>TaskContentServiceImpl</code>) never decodes a Yjs update — it just orders (<code>sequenceNumber</code>) and relays opaque blobs. This is why snapshotting had to move from a server-side background job (as originally sketched) to <strong>client-reported</strong> snapshots: there is no Yjs runtime on the Java side to merge updates into a document state. <code>TaskContentSnapshotJob</code> only flags which Tasks are overdue; a connected client does the actual capture via <code>POST .../content/snapshot</code>.</p></li><li><p><strong>Canvas text layout/measurement</strong> — implemented and browser-verified (<code>CanvasRenderingContext2D.measureText()</code>-based line wrapping, click-to-position).</p></li><li><p><strong>Vietnamese IME through the hidden input</strong> — implemented and browser-verified with a synthesized Vietnamese composition sequence (<code>compositionstart/update/end</code>).</p></li><li><p><strong>WebSocket infrastructure</strong> — implemented: <code>spring-boot-starter-websocket</code>, STOMP broker at <code>/topic</code>, <code>WsJwtHandshakeInterceptor</code> validates the JWT (query param) at handshake and binds the resolved user as the STOMP session&#39;s <code>Principal</code> via a custom <code>DefaultHandshakeHandler</code>. <code>SecurityConfig</code> permits <code>/ws/tasks/**</code> at the HTTP filter-chain level since auth happens at the handshake, not via <code>JwtAuthenticationFilter</code> (which only reads the <code>Authorization</code> header, absent on a WS upgrade request).</p></li><li><p><strong>Offline conflict on reconnect</strong> — <strong>not implemented</strong>. <code>useTaskContentSync</code> just reconnects (<code>reconnectDelay: 3000</code>); there is no IndexedDB queue, so edits made fully offline (no WS at all, e.g. airplane mode) are not persisted if the tab closes before reconnecting. In-memory Yjs state survives a transient disconnect while the tab stays open.</p></li><li><p><strong>Snapshot/compaction job</strong> — implemented as a log-only warning (<code>TaskContentSnapshotJob</code>), not an actual compactor: old <code>task_content_operations</code> rows are never deleted/archived, so the log grows unbounded. This was an explicit simplification (lower risk) over building real compaction.</p></li><li><p><strong>Font auto-conversion on publish</strong> — <strong>not implemented</strong> (no publish flow exists yet to hook into; see task.md).</p></li></ul>`,18)])])}const m=t(a,[["render",d]]);export{h as __pageData,m as default};
